// Fonts for the link-preview image (api/og.js), as base64 so they travel inside the function
// bundle with no file-tracing or vercel.json setup to get wrong. The leading underscore keeps
// Vercel from treating this file as a function of its own (same as _forms.js).
//
// These are the Latin subsets of the faces the site already uses, copied from the @fontsource
// packages (newsreader, ibm-plex-sans, ibm-plex-mono), all under the SIL Open Font License 1.1.
// To add a weight: base64 the matching .woff from @fontsource/<family>/files and add it here.
// (.woff, not .woff2: the image renderer cannot read woff2.)

const b = (s) => Buffer.from(s, 'base64')

// Newsreader 600 — newsreader-latin-600-normal.woff
export const NEWSREADER_600 = b('')

// Newsreader 600, Latin Extended (accented letters in player names) — newsreader-latin-ext-600-normal.woff
export const NEWSREADER_600_EXT = b('')

// IBM Plex Sans 500 — ibm-plex-sans-latin-500-normal.woff
export const PLEX_SANS_500 = b('')

// IBM Plex Sans 700 — ibm-plex-sans-latin-700-normal.woff
export const PLEX_SANS_700 = b('')

// IBM Plex Mono 500 — ibm-plex-mono-latin-500-normal.woff
export const PLEX_MONO_500 = b('')
